  const fnt=w=>F[(w.b?"b":"")+(w.i?"i":"")];const ZWART=rgb(.1,.1,.1),LIJN=rgb(.8,.8,.8);
  let pg=null,y=0;const nieuw=()=>{pg=doc.addPage([breed,hoog]);y=hoog-marge};
