  const sc=d=>{const v=norm(inkVan(d)+" "+d.naam);return w.filter(x=>v.includes(x)).length};
  const D=inkDocs().map(d=>({d,s:sc(d)})).sort((x,y)=>y.s-x.s||inkDatum(y.d).localeCompare(inkDatum(x.d))).slice(0,60).map(x=>x.d);
