/* ============ Rechten per gebruiker en per functie ============
   bestuur.rechten = null → volgens het profiel (admin / boekhouder / lezer)
   bestuur.rechten = {functie:"geen"|"lezen"|"bewerken"} → "geen" verbergt de functie (menu + pagina),
   "lezen" toont ze zonder te kunnen wijzigen, "bewerken" laat wijzigen toe. De database dwingt het bewerken af (functie mag()).
   Een administrator heeft altijd alle rechten. */
var RECHTEN=null;
const FUNC=[["leden","Ledenlijst",["leden"],"Leden"],["punten","Puntensysteem",["punten"],"Leden"],
  ["overzicht","Overzicht",["boekhouding"],"Financiën"],["financien","Transacties",["boekingen","verwerken"],"Financiën"],["facturen","Facturen",["facturen","inkomend"],"Financiën"],["begroting","Begroting",["begroting"],"Financiën"],["historiek","Historiek",["historiek"],"Financiën"],["kassa","Kassa",["kassa"],"Financiën"],
  ["kalenders","Kalenders",["kalenders","ronde","kalcontrole"],"Activiteiten"],["kalverdeling","Dozen meegeven of terugbrengen",[],"Activiteiten"],["fuif","In Vier en Vlam",["fuif"],"Activiteiten"],["banket","Banket",["banket"],"Activiteiten"],["kinderfeest","Kinderfeest",["kinderfeest"],"Activiteiten"],["familiedag","Familiedag",["familiedag"],"Activiteiten"],
  ["agenda","Agenda en verslagen",["agenda","verslagen"],"Administratie"],["mails","Communicatie – mail",["mails"],"Administratie"],["social","Communicatie – sociale media",["social"],"Administratie"],["sms","Communicatie – sms",["sms"],"Administratie"],["sponsors","Sponsors",["sponsors"],"Administratie"],["documenten","Documenten",["documenten"],"Administratie"],["website","Website",["website"],"Administratie"],["shiften","Shiften",["shiften"],"Administratie"],["fotos","Fotoalbums",["fotos"],"Administratie"],
  ["webshop","Webshop",["webshop"],"Webshop"]];
const FUNC_VAN={};for(const [f,,rs] of FUNC)for(const r of rs)FUNC_VAN[r]=f;
const RECHT_LBL={geen:"Verborgen",lezen:"Lezen",bewerken:"Bewerken"};
function rechtenVanProfiel(rol){const o={};for(const [f] of FUNC)o[f]=rol==="admin"?"bewerken":rol==="boekhouder"&&["financien","facturen","terug","overzicht","historiek","begroting"].includes(f)?"bewerken":"lezen";return o}
function recht(r){r=(typeof NAV_ALIAS!=="undefined"&&NAV_ALIAS[r])||r;if(ROL==="admin")return "bewerken";const f=FUNC_VAN[r];if(!f)return "lezen";if(f==="sms")return (RECHTEN&&ROL===ROL_ECHT&&RECHTEN.sms)||"geen"; // sms: standaard verborgen voor iedereen behalve de administrator

  if(RECHTEN&&ROL===ROL_ECHT)return RECHTEN[f]||"geen";return ROL==="boekhouder"&&BOEK_ROUTES.has(r)?"bewerken":"lezen"}
magSchrijven=function(r){return recht(r||route())==="bewerken"};
// menu en toegang: verborgen functies uit het menu halen en de pagina niet tonen
let NAV_ORIG=null;
function navFilter(){if(!NAV_ORIG)NAV_ORIG=NAV.map(n=>Array.isArray(n)?n:{...n,items:[...n.items]});
  const nieuw=NAV_ORIG.map(n=>Array.isArray(n)?(recht(n[0])==="geen"?null:n):{...n,items:n.items.filter(i=>recht(i[0])!=="geen")}).filter(n=>n&&(Array.isArray(n)||n.items.length));
  NAV.length=0;NAV.push(...nieuw)}
{const _r=render;render=function(){if(typeof ROL!=="undefined"){navFilter();if(recht(route())==="geen"&&route()!=="dashboard"){location.hash="#dashboard";return}}return _r.apply(this,arguments)}}
