function rechtRuw(f){if(ROL==="admin")return"bewerken";const R=(typeof SIM_U!=="undefined"&&SIM_U&&ROL!==ROL_ECHT&&SIM_U.rechten)||(RECHTEN&&ROL===ROL_ECHT?RECHTEN:null);return R?(R[f]||"geen"):null}
